  const effectiveTileZoom = Math.min(18, Math.max(13, Math.round(16 + Math.log2(zoomLevel))));
  const approxGsdMeters = (156543 * Math.cos((centerLat * Math.PI) / 180) / Math.pow(2, effectiveTileZoom)).toFixed(1);

