        // Sample real satellite orthophoto RGB at pixel center
        let r = 130;
        let g = 140;
        let b = 95;

        if (ctx && centerX >= 0 && centerX < 600 && centerY >= 0 && centerY < 400) {
          try {
            const data = ctx.getImageData(centerX, centerY, 1, 1).data;
            if (data[3] > 0) {
              r = data[0];
              g = data[1];
              b = data[2];
