                  {/* 1. Underlying GEE Live Tiles if active */}
                  {geeStatus === 'active' && geeMetadata?.tileUrlTemplate && (
                    <g opacity="0.65">
                      {satelliteTiles.map((tile) => {
                        const tileUrl = geeMetadata.tileUrlTemplate!
                          .replace('{z}', String(tile.z))
